out = {}
for vid, s in src.items():
    p, n, q, a, extra = T[vid]
    pt = [x['text'] for x in s['phrases']]
    assert len(p) == len(pt) and len(n) == len(s['nouns']), vid
    rec, used = [], 0
    for r in s['recall']:
        if r in pt: rec.append(p[pt.index(r)])
        elif r in s['nouns']: rec.append(n[s['nouns'].index(r)])
        else: rec.append(extra); used += 1
    assert used == 1, vid
    out[vid] = {"phrases": p, "nouns": n, "question": q, "answer": a, "captions": {}, "recall": rec}
assert set(out) == set(src)
json.dump(out, open(f'{H}/tr/b002/de/hu.json', 'w'), ensure_ascii=False, indent=1)
